const teal = Color(0xFF087F78);
const ink = Color(0xFF183331);
final money = NumberFormat.currency(locale: 'en_PH', symbol: '₱', decimalDigits: 2);
final dateFmt = DateFormat('MMM d, yyyy');

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Store.instance.init();
  runApp(const PaisaTrackApp());
}

class Store {
  Store._();
  static final instance = Store._();
  late Database db;

  Future<void> init() async {
    final dir = await getDatabasesPath();
    db = await openDatabase(p.join(dir, 'paisatrack_lite.db'), version: 1,
      onCreate: (d, v) async {
        await d.execute('''CREATE TABLE borrowers(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, notes TEXT, createdAt TEXT NOT NULL)''');
        await d.execute('''CREATE TABLE loans(id INTEGER PRIMARY KEY AUTOINCREMENT, borrowerId INTEGER NOT NULL, principal REAL NOT NULL, rate REAL NOT NULL, days INTEGER NOT NULL, frequency TEXT NOT NULL, startDate TEXT NOT NULL, dueDate TEXT NOT NULL, total REAL NOT NULL, agreedPayment REAL NOT NULL, createdAt TEXT NOT NULL)''');
        await d.execute('''CREATE TABLE entries(id INTEGER PRIMARY KEY AUTOINCREMENT, loanId INTEGER NOT NULL, amount REAL NOT NULL, kind TEXT NOT NULL, entryDate TEXT NOT NULL, note TEXT)''');
      });
  }

  Future<List<Map<String, Object?>>> borrowers() => db.rawQuery('SELECT * FROM borrowers ORDER BY name COLLATE NOCASE');
  Future<int> addBorrower(String name, String phone, String notes) => db.insert('borrowers', {'name': name, 'phone': phone, 'notes': notes, 'createdAt': DateTime.now().toIso8601String()});
  Future<int> addLoan(Map<String, Object?> row) => db.insert('loans', row);
  Future<int> addEntry(int loanId, double amount, String kind, String note) => db.insert('entries', {'loanId': loanId, 'amount': amount, 'kind': kind, 'entryDate': DateTime.now().toIso8601String(), 'note': note});
  Future<List<Map<String, Object?>>> loansFor(int borrowerId) async => db.rawQuery('SELECT l.*, (SELECT COALESCE(SUM(e.amount),0) FROM entries e WHERE e.loanId=l.id AND e.kind="payment") AS paid, (SELECT COUNT(*) FROM entries e WHERE e.loanId=l.id AND e.kind="missed") AS missed FROM loans l WHERE borrowerId=? ORDER BY startDate DESC', [borrowerId]);
  Future<List<Map<String, Object?>>> allLoans() => db.rawQuery('SELECT l.*, b.name AS borrowerName, (SELECT COALESCE(SUM(e.amount),0) FROM entries e WHERE e.loanId=l.id AND e.kind="payment") AS paid FROM loans l JOIN borrowers b ON b.id=l.borrowerId ORDER BY l.dueDate');
  Future<List<Map<String, Object?>>> entriesFor(int loanId) => db.query('entries', where: 'loanId=?', whereArgs: [loanId], orderBy: 'entryDate DESC');
  Future<List<Map<String, Object?>>> recentEntries() => db.rawQuery('SELECT e.*, b.name AS borrowerName, l.id AS loanNumber FROM entries e JOIN loans l ON l.id=e.loanId JOIN borrowers b ON b.id=l.borrowerId ORDER BY e.entryDate DESC LIMIT 8');
  Future<double> collectedToday() async { final today = DateFormat('yyyy-MM-dd').format(DateTime.now()); final r = await db.rawQuery('SELECT COALESCE(SUM(amount),0) AS total FROM entries WHERE kind="payment" AND substr(entryDate,1,10)=?', [today]); return (r.first['total'] as num).toDouble(); }
  Future<double> outstanding() async { final r = await db.rawQuery('SELECT COALESCE(SUM(l.total - (SELECT COALESCE(SUM(e.amount),0) FROM entries e WHERE e.loanId=l.id AND e.kind="payment")),0) AS total FROM loans l'); return (r.first['total'] as num).toDouble(); }
  Future<int> activeBorrowers() async { final r = await db.rawQuery('SELECT COUNT(DISTINCT l.borrowerId) AS n FROM loans l WHERE l.total > (SELECT COALESCE(SUM(e.amount),0) FROM entries e WHERE e.loanId=l.id AND e.kind="payment")'); return r.first['n'] as int; }
  Future<void> deleteLoan(int id) async { await db.transaction((t) async { await t.delete('entries', where: 'loanId=?', whereArgs: [id]); await t.delete('loans', where: 'id=?', whereArgs: [id]); }); }
  Future<Map<String, dynamic>> exportData() async {
    return {'format': 'paisatrack-lite-backup-v1', 'exportedAt': DateTime.now().toIso8601String(), 'borrowers': await db.query('borrowers'), 'loans': await db.query('loans'), 'entries': await db.query('entries')};
  }
  Future<void> importData(Map<String, dynamic> data) async {
    if (data['format'] != 'paisatrack-lite-backup-v1') throw Exception('This is not a PaisaTrack Lite backup file.');
    await db.transaction((t) async {
      await t.delete('entries'); await t.delete('loans'); await t.delete('borrowers');
      for (final row in (data['borrowers'] as List)) { await t.insert('borrowers', Map<String, Object?>.from(row)); }
      for (final row in (data['loans'] as List)) { await t.insert('loans', Map<String, Object?>.from(row)); }
      for (final row in (data['entries'] as List)) { await t.insert('entries', Map<String, Object?>.from(row)); }
    });
  }
}

class PaisaTrackApp extends StatelessWidget {
  const PaisaTrackApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(title: 'PaisaTrack Lite', debugShowCheckedModeBanner: false, theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: teal), scaffoldBackgroundColor: const Color(0xFFF5F8F7), appBarTheme: const AppBarTheme(backgroundColor: Color(0xFFF5F8F7), foregroundColor: ink, elevation: 0), useMaterial3: true, inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(13), borderSide: BorderSide.none))), home: const HomePage());
}

class HomePage extends StatefulWidget { const HomePage({super.key}); @override State<HomePage> createState() => _HomePageState(); }
class _HomePageState extends State<HomePage> {
  int tab = 0; int refresh = 0;
  void reload() => setState(() => refresh++);
  @override Widget build(BuildContext context) {
    return Scaffold(appBar: AppBar(title: const Row(children: [Icon(Icons.account_balance_wallet_rounded, color: teal), SizedBox(width: 9), Text('PaisaTrack Lite', style: TextStyle(fontWeight: FontWeight.w800))]), actions: [IconButton(tooltip: 'Backup and restore', onPressed: backupMenu, icon: const Icon(Icons.backup_outlined))]),
      body: IndexedStack(index: tab, children: [Dashboard(key: ValueKey('d$refresh'), onChanged: reload), BorrowersPage(key: ValueKey('b$refresh'), onChanged: reload)]),
      bottomNavigationBar: NavigationBar(selectedIndex: tab, onDestinationSelected: (v) => setState(() => tab=v), destinations: const [NavigationDestination(icon: Icon(Icons.dashboard_outlined), selectedIcon: Icon(Icons.dashboard), label: 'Home'), NavigationDestination(icon: Icon(Icons.people_outline), selectedIcon: Icon(Icons.people), label: 'Borrowers')]),
      floatingActionButton: tab == 1 ? FloatingActionButton.extended(backgroundColor: teal, foregroundColor: Colors.white, onPressed: () => addBorrower(context, reload), icon: const Icon(Icons.person_add_alt_1), label: const Text('Add borrower')) : null);
  }
  Future<void> backupMenu() async {
    if (!mounted) return;
    showModalBottomSheet(context: context, builder: (ctx) => SafeArea(child: Wrap(children: [ListTile(leading: const Icon(Icons.upload_file), title: const Text('Create backup'), subtitle: const Text('Save a copy of all borrowers, loans and payments'), onTap: () { Navigator.pop(ctx); createBackup(context); }), ListTile(leading: const Icon(Icons.restore), title: const Text('Restore backup'), subtitle: const Text('Replace current records with a backup file'), onTap: () { Navigator.pop(ctx); restoreBackup(context, reload); })])));
  }
}

