    if (!snap.hasData) return const Center(child: CircularProgressIndicator());
    final collected=snap.data![0] as double, outstanding=snap.data![1] as double, people=snap.data![2] as int, recent=snap.data![3] as List<Map<String,Object?>>, loans=snap.data![4] as List<Map<String,Object?>>;
    final overdue=loans.where((l) => _balance(l)>0 && DateTime.parse(l['dueDate'] as String).isBefore(DateTime.now())).length;
    return ListView(padding: const EdgeInsets.fromLTRB(18, 8, 18, 24), children: [const Text('Good day!', style: TextStyle(color: Colors.black54)), const Text('Here is your lending summary.', style: TextStyle(fontSize: 21, fontWeight: FontWeight.w800, color: ink)), const SizedBox(height: 18), Container(padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: teal, borderRadius: BorderRadius.circular(22)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text("TOTAL OUTSTANDING", style: TextStyle(color: Colors.white70, fontWeight: FontWeight.w700, fontSize: 11, letterSpacing: 1)), const SizedBox(height: 6), Text(money.format(outstanding), style: const TextStyle(color: Colors.white, fontSize: 30, fontWeight: FontWeight.w800)), const SizedBox(height: 14), Row(children: [const Icon(Icons.trending_up, color: Colors.white70, size: 17), const SizedBox(width: 6), Text('$people active borrowers', style: const TextStyle(color: Colors.white))])])), const SizedBox(height: 12), Row(children: [Expanded(child: _metric('Collected today', money.format(collected), Icons.payments_outlined)), const SizedBox(width: 10), Expanded(child: _metric('Overdue loans', '$overdue', Icons.warning_amber_rounded))]), const SizedBox(height: 22), const Text('Loans to watch', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800, color: ink)), const SizedBox(height: 9), ...loans.where((l)=>_balance(l)>0).take(5).map((l)=>_loanTile(context,l,onChanged)), const SizedBox(height: 20), const Text('Recent activity', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800, color: ink)), const SizedBox(height: 8), if (recent.isEmpty) const _empty('No payments recorded yet.'), ...recent.map((e)=>ListTile(contentPadding: EdgeInsets.zero, leading: CircleAvatar(backgroundColor: e['kind']=='payment'?const Color(0xFFE0F3EE):const Color(0xFFFFE9D9), child: Icon(e['kind']=='payment'?Icons.call_received:Icons.event_busy, color: e['kind']=='payment'?teal:Colors.deepOrange)), title: Text(e['borrowerName'] as String, style: const TextStyle(fontWeight: FontWeight.w700)), subtitle: Text(e['kind']=='payment'?'Payment · ${dateFmt.format(DateTime.parse(e['entryDate'] as String))}':'Missed payment · ${dateFmt.format(DateTime.parse(e['entryDate'] as String))}'), trailing: Text(e['kind']=='payment'?money.format(e['amount']):'Skipped', style: TextStyle(fontWeight: FontWeight.w800, color: e['kind']=='payment'?teal:Colors.deepOrange))))]);
