double _balance(Map<String,Object?> l) => ((l['total'] as num).toDouble() - ((l['paid'] as num?)?.toDouble() ?? 0)).clamp(0, double.infinity).toDouble();
Widget _metric(String label,String value,IconData icon)=>Container(padding: const EdgeInsets.all(15), decoration: BoxDecoration(color: Colors.white,borderRadius: BorderRadius.circular(17)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Icon(icon,color:teal),const SizedBox(height:10),Text(value,style:const TextStyle(fontWeight:FontWeight.w800,fontSize:17,color:ink)),Text(label,style:const TextStyle(color:Colors.black54,fontSize:12))]));
Widget _empty(String s)=>Container(padding: const EdgeInsets.all(22), decoration: BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16)), child: Center(child:Text(s,style:const TextStyle(color:Colors.black54))));
Widget _loanTile(BuildContext context,Map<String,Object?> l,VoidCallback changed)=>Card(color:Colors.white,elevation:0,child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:14,vertical:3), title:Text('${l['borrowerName']} · ${money.format(_balance(l))}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('Due ${dateFmt.format(DateTime.parse(l['dueDate'] as String))} · ${_loanStatus(l)}'),trailing:const Icon(Icons.chevron_right),onTap:()=>loanDetails(context,l,changed)));
String _loanStatus(Map<String,Object?> l) { if (_balance(l)<=0.005) return 'Paid'; if(DateTime.parse(l['dueDate'] as String).isBefore(DateTime.now())) return 'Overdue'; return 'Active'; }

